/**
 * Registry of procedural families by name (ROADMAP A1, M1.F). The dump CLI
 * (`npm run dump:families`), the registry test and, later, the selector (M1.14) resolve
 * families here.
 *
 * Family implementers do NOT edit this file: each family lives in its own
 * `web/src/tasks/<family>/` directory and is dumped with `--module` until an integrator adds
 * it here as `[family.name]: family`. The toy `_example` family is never registered.
 *
 * Every registered family must also have an entry in `registry.test.ts` (its property options),
 * and its bank twin in `hb.gen.registry` with a `golden/ts_dumps/<name>.json` dump (A1, A17).
 */

import { coding } from './coding'
import type { AnyFamily } from './family'
import { matrices } from './matrices'
import { quant } from './quant'
import { reading } from './reading'
import { rotation } from './rotation'
import { rt } from './rt'
import { series } from './series'
import { corsi, spanBwd, spanFwd } from './span'

/**
 * M1 procedural families (§4.2, §14.3 M1), keyed by `family.name`: power items rotation (M1.5),
 * matrices (M1.6), series (M1.7) and quant (M1.8); blocks span_fwd, span_bwd and corsi (M1.9),
 * rt (M1.10), coding (M1.11) and reading (M1.12).
 */
const REGISTERED: readonly AnyFamily[] = [rotation, matrices, series, quant, spanFwd, spanBwd, corsi, rt, coding, reading]

/**
 * The registered names, in registry order. Kept as a string literal on purpose: the bank's
 * `tests/gen/test_registry.py` reads it from this file to check that `hb.gen.registry` and the
 * `golden/ts_dumps/<name>.json` dumps cover the same families (A1, A17). `registry.test.ts`
 * checks it equals the keys of {@link FAMILIES}.
 */
export const FAMILY_NAMES = ['rotation', 'matrices', 'series', 'quant', 'span_fwd', 'span_bwd', 'corsi', 'rt', 'coding', 'reading'] as const

export const FAMILIES: Readonly<Record<string, AnyFamily>> = Object.freeze(Object.fromEntries(REGISTERED.map((f) => [f.name, f])))

/** The registered family called `name`, or undefined. */
export function getFamily(name: string): AnyFamily | undefined {
  return Object.hasOwn(FAMILIES, name) ? FAMILIES[name] : undefined
}
